    // App: ECL | Module: ECL Report (FunctionId 561)
    // Client request 2026-08-20: page was slow to load because the GET itself fetched every
    // outlay row (GetOutlaysAsync, unfiltered by default = every demand) before rendering anything.
    // Now renders the shell (filters only, no rows) immediately - the grid loads separately via
    // DataAnalysisData below, called by JS with a loading spinner shown meanwhile.
    [HttpGet]
    public async Task<IActionResult> DataAnalysis(int? demandId, int? categoryId, string? financialYear, CancellationToken ct)
    {
        ViewData["Title"] = "Data Analysis";
        ViewData["Breadcrumb"] = "ECL / ECL Report / Data Analysis";

        var session = HttpContext.Session.GetUbisSession();
        if (session == null) return await ExpiredSessionRedirectAsync();
        if (!session.HasPermission(DataAnalysisFunctionId)) return Forbid();

        var model = await BuildFilterShellAsync(session, "ECL - Data Analysis", demandId, categoryId, financialYear, ct);
        model.ShowCategoryFilter = true;
        return View(model);
    }

    /// <summary>AJAX companion to DataAnalysis — does the actual (potentially slow) row fetch and
    /// groups it by Demand to match the client-supplied report format screenshot (2026-08-20): each
    /// Demand is a group header row, its Scheme rows underneath (Category, 10 year-outlay columns),
    /// then Total Outlay/Total Actual subtotal rows summed across that Demand's schemes. Skips the
    /// "C.Share / Remaining Year wise C.Share" column per that same instruction - CentralShare isn't
    /// included in the response at all. Returns the aggregation result as JSON; ecl.js renders it
    /// into the two side-by-side tables (financial data left, remarks/approval right).</summary>
    [HttpGet]
    public async Task<IActionResult> DataAnalysisData(int? demandId, int? categoryId, string? financialYear, CancellationToken ct)
    {
        var session = HttpContext.Session.GetUbisSession();
        if (session == null) return Unauthorized();
        if (!session.HasPermission(DataAnalysisFunctionId)) return Forbid();

        var fy = string.IsNullOrWhiteSpace(financialYear) ? session.FinancialYear : financialYear;
        var categoriesResult = await _eclClient.GetCategoriesAsync(session.Token, fy, ct);
        var categories = categoriesResult.Data ?? new List<EclCategoryDto>();

        var rowsResult = await _eclClient.GetOutlaysAsync(session.Token, demandId, categoryId, null, fy, ct);
        if (!rowsResult.IsSuccess)
        {
            return Json(new { success = false, message = rowsResult.Error?.Message ?? "Could not load report data." });
        }

        var rows = rowsResult.Data ?? new List<EclSchemeOutlayDto>();
        var groups = rows
            .GroupBy(r => r.DemandId)
            .OrderBy(g => rows.First(r => r.DemandId == g.Key).DemandNo)
            .Select(g =>
            {
                var first = g.First();
                var totalOutlay = new decimal[10];
                var totalActual = new decimal[10];
                var schemeRows = g.OrderBy(r => r.SchemeSrNo).Select(r =>
                {
                    for (var i = 0; i < 10; i++)
                    {
                        totalOutlay[i] += r.Outlay != null && i < r.Outlay.Length ? r.Outlay[i] ?? 0 : 0;
                        totalActual[i] += r.Actuals != null && i < r.Actuals.Length ? r.Actuals[i] ?? 0 : 0;
                    }

                    return new
                    {
                        rowId = r.RowId,
                        schemeLabel = !string.IsNullOrEmpty(r.SchemeName) ? $"{r.SchemeSrNo ?? 0} - {r.SchemeName}" : $"Scheme #{r.SchemeId}",
                        categoryLabel = categories.FirstOrDefault(c => c.CategoryId == r.CategoryId)?.CategoryName ?? "",
                        outlay = r.Outlay ?? new decimal?[10],
                        userRemarks = r.UserRemarks,
                        approverRemarks = r.DoeRemarks,
                        approvedByDoe = r.ApprovedByDoe
                    };
                }).ToList();

                return new
                {
                    demandLabel = !string.IsNullOrEmpty(first.DemandName) ? $"{first.DemandNo} - {first.DemandName}" : $"Demand #{first.DemandId}",
                    rows = schemeRows,
                    totalOutlay,
                    totalActual
                };
            })
            .ToList();

        return Json(new { success = true, groups });
    }

    /// <summary>Export buttons on DataAnalysis.cshtml — same filters, same grouping as
    /// DataAnalysisData above (re-fetched rather than shared, since this needs string-formatted
    /// cells and the JSON endpoint needs typed values for client-side rendering), handed to the
    /// generic Reporting microservice (Core/Reporting) rather than generated in-process — see that
    /// service's own doc comments for why (reused across 50+ future pages, not ECL-specific).</summary>
    [HttpGet]
    public async Task<IActionResult> ExportPdf(int? demandId, int? categoryId, string? financialYear, CancellationToken ct) =>
        await ExportAsync(demandId, categoryId, financialYear, isPdf: true, ct);

    [HttpGet]
    public async Task<IActionResult> ExportExcel(int? demandId, int? categoryId, string? financialYear, CancellationToken ct) =>
        await ExportAsync(demandId, categoryId, financialYear, isPdf: false, ct);

    private async Task<IActionResult> ExportAsync(int? demandId, int? categoryId, string? financialYear, bool isPdf, CancellationToken ct)
    {
        var session = HttpContext.Session.GetUbisSession();
        if (session == null) return await ExpiredSessionRedirectAsync();
        if (!session.HasPermission(DataAnalysisFunctionId)) return Forbid();

        var fy = string.IsNullOrWhiteSpace(financialYear) ? session.FinancialYear : financialYear;

        var yearsResult = await _eclClient.GetFinancialYearsAsync(session.Token, ct);
        var years = yearsResult.Data?.FinancialYears ?? new List<string> { fy };

        var categoriesResult = await _eclClient.GetCategoriesAsync(session.Token, fy, ct);
        var categories = categoriesResult.Data ?? new List<EclCategoryDto>();

        var rowsResult = await _eclClient.GetOutlaysAsync(session.Token, demandId, categoryId, null, fy, ct);
        if (!rowsResult.IsSuccess)
        {
            TempData["ErrorMessage"] = rowsResult.Error?.Message ?? "Could not load report data.";
            return RedirectToAction("DataAnalysis", new { demandId, categoryId, financialYear });
        }

        var rows = rowsResult.Data ?? new List<EclSchemeOutlayDto>();

        var columns = new List<string> { "Demand / Scheme", "Category" };
        columns.AddRange(years);
        columns.Add("User Remarks");
        columns.Add("Approver Remarks");
        columns.Add("Approved By DOE");

        var groups = rows
            .GroupBy(r => r.DemandId)
            .OrderBy(g => rows.First(r => r.DemandId == g.Key).DemandNo)
            .Select(g =>
            {
                var first = g.First();
                var totalOutlay = new decimal[years.Count];
                var totalActual = new decimal[years.Count];

                var schemeRows = g.OrderBy(r => r.SchemeSrNo).Select(r =>
                {
                    var cells = new List<string>
                    {
                        !string.IsNullOrEmpty(r.SchemeName) ? $"{r.SchemeSrNo ?? 0} - {r.SchemeName}" : $"Scheme #{r.SchemeId}",
                        categories.FirstOrDefault(c => c.CategoryId == r.CategoryId)?.CategoryName ?? ""
                    };
                    for (var i = 0; i < years.Count; i++)
                    {
                        var outlay = r.Outlay != null && i < r.Outlay.Length ? r.Outlay[i] ?? 0 : 0;
                        var actual = r.Actuals != null && i < r.Actuals.Length ? r.Actuals[i] ?? 0 : 0;
                        totalOutlay[i] += outlay;
                        totalActual[i] += actual;
                        cells.Add(outlay.ToString("N2"));
                    }
                    cells.Add(r.UserRemarks ?? "");
                    cells.Add(r.DoeRemarks ?? "");
                    cells.Add(r.ApprovedByDoe ?? "");
                    return cells.ToArray();
                }).ToList();

                var totalOutlayCells = new List<string> { "Total Outlay", "" };
                totalOutlayCells.AddRange(totalOutlay.Select(v => v.ToString("N2")));
                totalOutlayCells.AddRange(new[] { "", "", "" });

                var totalActualCells = new List<string> { "Total Actual", "" };
                totalActualCells.AddRange(totalActual.Select(v => v.ToString("N2")));
                totalActualCells.AddRange(new[] { "", "", "" });

                return new ReportGroupDto
                {
                    Label = !string.IsNullOrEmpty(first.DemandName) ? $"{first.DemandNo} - {first.DemandName}" : $"Demand #{first.DemandId}",
                    Rows = schemeRows,
                    Totals = new List<ReportTotalRowDto>
                    {
                        new() { Cells = totalOutlayCells.ToArray() },
                        new() { Cells = totalActualCells.ToArray() }
                    }
                };
            })
            .ToList();

        var report = new TabularReportDto
        {
            Title = "Estimated Committed Liabilities",
            Subtitle = "(In Rs. Crores)",
            FileName = "ecl-data-analysis",
            Columns = columns,
            Groups = groups
        };

        var exportResult = isPdf
            ? await _reportingClient.ExportPdfAsync(session.Token, report, ct)
            : await _reportingClient.ExportExcelAsync(session.Token, report, ct);

        if (!exportResult.IsSuccess || exportResult.Data == null)
        {
            TempData["ErrorMessage"] = exportResult.Error?.Message ?? "Could not generate the export.";
            return RedirectToAction("DataAnalysis", new { demandId, categoryId, financialYear });
        }

        var contentType = isPdf ? "application/pdf" : "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet";
        var extension = isPdf ? "pdf" : "xlsx";
        return File(exportResult.Data, contentType, $"{report.FileName}.{extension}");
    }

    private async Task<EclReportViewModel> BuildFilterShellAsync(UbisSessionData session, string title, int? demandId, int? categoryId, string? financialYear, CancellationToken ct)
    {
        var fy = string.IsNullOrWhiteSpace(financialYear) ? session.FinancialYear : financialYear;

        var model = new EclReportViewModel
        {
            Title = title,
            SelectedDemandId = demandId,
            SelectedCategoryId = categoryId,
            FinancialYear = fy
        };

        var demandsResult = await _aimClient.GetMyDemandsAsync(session.Token, session.FinancialYear, ct);
        model.Demands = demandsResult.IsSuccess ? demandsResult.Data?.Demands ?? new List<DemandDto>() : new List<DemandDto>();

        var categoriesResult = await _eclClient.GetCategoriesAsync(session.Token, fy, ct);
        model.Categories = categoriesResult.Data ?? new List<EclCategoryDto>();

        var yearsResult = await _eclClient.GetFinancialYearsAsync(session.Token, ct);
        model.FinancialYearOptions = yearsResult.Data?.FinancialYears ?? new List<string> { fy };

        if (TempData["ErrorMessage"] is string exportError)
        {
            model.StatusIsError = true;
            model.StatusMessage = exportError;
        }

        return model;
    }

