    private async Task<IActionResult> ExportStatusReportAsync(int functionId, string screenActionName, string title, string fileName, int? demandId, string? financialYear, Func<EclSchemeOutlayDto, bool>? rowFilter, bool isPdf, CancellationToken ct)
    {
        var session = HttpContext.Session.GetUbisSession();
        if (session == null) return await ExpiredSessionRedirectAsync();
        if (!session.HasPermission(functionId)) return Forbid();

        var fy = string.IsNullOrWhiteSpace(financialYear) ? session.FinancialYear : financialYear;

        var rowsResult = await _eclClient.GetOutlaysAsync(session.Token, demandId, null, null, fy, ct);
        if (!rowsResult.IsSuccess)
        {
            TempData["ErrorMessage"] = rowsResult.Error?.Message ?? "Could not load report data.";
            return RedirectToAction(screenActionName, new { demandId, financialYear });
        }

        var rows = rowsResult.Data ?? new List<EclSchemeOutlayDto>();
        if (rowFilter != null)
        {
            rows = rows.Where(rowFilter).ToList();
        }

        var dataRows = rows.Select((r, i) => new[]
        {
            (i + 1).ToString(),
            r.FinancialYear ?? "",
            !string.IsNullOrEmpty(r.DemandName) ? $"{r.DemandNo} - {r.DemandName}" : $"Demand #{r.DemandId}",
            !string.IsNullOrEmpty(r.SchemeName) ? $"{r.SchemeSrNo ?? 0} - {r.SchemeName}" : $"Scheme #{r.SchemeId}",
            r.TotalOutlay?.ToString("N2") ?? "",
            r.CentralShare?.ToString("N2") ?? "",
            r.DoeApprovalStatusDisplay
        }).ToList();

        var report = new TabularReportDto
        {
            Title = title,
            Subtitle = "Amount in Crores of Rupees",
            FileName = fileName,
            Columns = new List<string> { "Sr. No.", "Financial Year", "Demand", "Scheme", "Total Outlay", "Central Share", "Status" },
            Groups = new List<ReportGroupDto> { new() { Rows = dataRows } }
        };

        var exportResult = isPdf
            ? await _reportingClient.ExportPdfAsync(session.Token, report, ct)
            : await _reportingClient.ExportExcelAsync(session.Token, report, ct);

        if (!exportResult.IsSuccess || exportResult.Data == null)
        {
            TempData["ErrorMessage"] = exportResult.Error?.Message ?? "Could not generate the export.";
            return RedirectToAction(screenActionName, new { demandId, financialYear });
        }

        var contentType = isPdf ? "application/pdf" : "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet";
        var extension = isPdf ? "pdf" : "xlsx";
        return File(exportResult.Data, contentType, $"{fileName}.{extension}");
    }

    private async Task<EclReportViewModel> BuildReportAsync(UbisSessionData session, string title, int? demandId, int? categoryId, string? financialYear, Func<EclSchemeOutlayDto, bool>? rowFilter, CancellationToken ct)
    {
        var fy = string.IsNullOrWhiteSpace(financialYear) ? session.FinancialYear : financialYear;

        var model = new EclReportViewModel
        {
            Title = title,
            SelectedDemandId = demandId,
            SelectedCategoryId = categoryId,
            FinancialYear = fy
        };

        var demandsResult = await _aimClient.GetMyDemandsAsync(session.Token, session.FinancialYear, ct);
        model.Demands = demandsResult.IsSuccess ? demandsResult.Data?.Demands ?? new List<DemandDto>() : new List<DemandDto>();

        var categoriesResult = await _eclClient.GetCategoriesAsync(session.Token, fy, ct);
        model.Categories = categoriesResult.Data ?? new List<EclCategoryDto>();

        var yearsResult = await _eclClient.GetFinancialYearsAsync(session.Token, ct);
        model.FinancialYearOptions = yearsResult.Data?.FinancialYears ?? new List<string> { fy };

        var rowsResult = await _eclClient.GetOutlaysAsync(session.Token, demandId, categoryId, null, fy, ct);
        var rows = rowsResult.Data ?? new List<EclSchemeOutlayDto>();
        model.Rows = rowFilter == null ? rows : rows.Where(rowFilter).ToList();

        if (!rowsResult.IsSuccess)
        {
            model.StatusIsError = true;
            model.StatusMessage = rowsResult.Error?.Message ?? "Could not load report data.";
        }
        else if (TempData["ErrorMessage"] is string exportError)
        {
            // Surfaces the export-failure message set by ExportStatusReportAsync's RedirectToAction —
            // without this, a failed PDF/Excel export would silently bounce back to this screen with
            // no visible feedback at all.
            model.StatusIsError = true;
            model.StatusMessage = exportError;
        }

        return model;
    }

    // Client requirement 2026-08-27 ("also make same changes for ECL and SBE modules" - see
    // PreBudgetMeetingController's matching IsAjaxRequest()/ExpiredSessionRedirectAsync): AJAX
    // requests now get a clean 401 instead of a redirect an XHR caller could mistake for real data.
    private bool IsAjaxRequest() =>
        string.Equals(Request.Headers["X-Requested-With"], "XMLHttpRequest", StringComparison.OrdinalIgnoreCase);

    private async Task<IActionResult> ExpiredSessionRedirectAsync()
    {
        await HttpContext.SignOutAsync(CookieAuthenticationDefaults.AuthenticationScheme);
        if (IsAjaxRequest())
        {
            return Unauthorized();
        }
        return RedirectToAction("Login", "User", new { area = "" });
    }

